int main() {
    // 分配代码段
    void *code_seg = mmap(NULL, 4096, PROT_READ | PROT_EXEC,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (code_seg == MAP_FAILED) {
        perror("mmap code");
