#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

int main() {
    // 使用标准C库
    FILE *fp = fopen("test.txt", "r");
    if (!fp) {
        // 错误处理
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return 1;
    }

    // 使用系统调用接口
