## 12.3 线程池

### 线程池的实现

线程池的主要组件：
1. 任务队列
2. 工作线程
3. 线程管理
4. 任务调度

示例代码：
```c:source/_posts/程序员自我修养/code/thread_pool.c
#include <stdio.h>
#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

#define THREAD_COUNT 4
#define QUEUE_SIZE 10

// 任务结构
typedef struct {
    void (*func)(void *);
    void *arg;
} task_t;

// 线程池结构
typedef struct {
    pthread_t threads[THREAD_COUNT];
    task_t queue[QUEUE_SIZE];
    int queue_size;
    int queue_head;
    int queue_tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int shutdown;
} thread_pool_t;

// 初始化线程池
thread_pool_t *pool_init() {
    thread_pool_t *pool = malloc(sizeof(thread_pool_t));
    if (!pool) return NULL;

    pool->queue_size = 0;
    pool->queue_head = 0;
    pool->queue_tail = 0;
    pool->shutdown = 0;

    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);

    // 创建工作线程
    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_create(&pool->threads[i], NULL, worker, pool);
    }

    return pool;
}

// 工作线程函数
void *worker(void *arg) {
    thread_pool_t *pool = arg;

    while (1) {
        pthread_mutex_lock(&pool->mutex);

        // 等待任务
        while (pool->queue_size == 0 && !pool->shutdown) {
            pthread_cond_wait(&pool->cond, &pool->mutex);
        }

        if (pool->shutdown) {
            pthread_mutex_unlock(&pool->mutex);
            break;
        }

        // 获取任务
        task_t task = pool->queue[pool->queue_head];
        pool->queue_head = (pool->queue_head + 1) % QUEUE_SIZE;
        pool->queue_size--;

        pthread_mutex_unlock(&pool->mutex);

        // 执行任务
        task.func(task.arg);
    }

    return NULL;
}

// 添加任务
void pool_add_task(thread_pool_t *pool, void (*func)(void *), void *arg) {
    pthread_mutex_lock(&pool->mutex);

    // 等待队列有空间
    while (pool->queue_size == QUEUE_SIZE) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }

    // 添加任务
    pool->queue[pool->queue_tail].func = func;
    pool->queue[pool->queue_tail].arg = arg;
    pool->queue_tail = (pool->queue_tail + 1) % QUEUE_SIZE;
    pool->queue_size++;

    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
}

// 销毁线程池
void pool_destroy(thread_pool_t *pool) {
    pthread_mutex_lock(&pool->mutex);
    pool->shutdown = 1;
    pthread_cond_broadcast(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);

    // 等待所有线程结束
    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_join(pool->threads[i], NULL);
    }

    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}
```

### 线程池的使用

线程池的使用方法：
1. 创建线程池
2. 添加任务
3. 等待任务完成
4. 销毁线程池

示例代码：
```c:source/_posts/程序员自我修养/code/pool_usage.c
