    int id = *(int *)arg;
    printf("Task %d is running\n", id);
    sleep(1);
    printf("Task %d is done\n", id);
}

int main() {
    // 创建线程池
    thread_pool_t *pool = pool_init();
    if (!pool) return 1;

    // 添加任务
    int task_ids[10];
    for (int i = 0; i < 10; i++) {
        task_ids[i] = i;
        pool_add_task(pool, task_func, &task_ids[i]);
    }

    // 等待一段时间
    sleep(5);

    // 销毁线程池
