#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SIZE 1000000

void slow_function() {
    int *arr = malloc(SIZE * sizeof(int));
    for (int i = 0; i < SIZE; i++) {
        arr[i] = i;
    }
    free(arr);
}

void fast_function() {
    int *arr = malloc(SIZE * sizeof(int));
    for (int i = 0; i < SIZE; i += 16) {
        arr[i] = i;
    }
    free(arr);
}

int main() {
    clock_t start, end;

    // 测试慢函数
    start = clock();
    slow_function();
    end = clock();
    printf("Slow function time: %f seconds\n", 
           (double)(end - start) / CLOCKS_PER_SEC);

    // 测试快函数
    start = clock();
    fast_function();
    end = clock();
    printf("Fast function time: %f seconds\n", 
           (double)(end - start) / CLOCKS_PER_SEC);

    return 0;
}
```

