    while (i + 8 <= n) {
        *(uint64_t *)(dst + i) = *(const uint64_t *)(src + i);
        i += 8;
    }

    // 处理剩余字节
    while (i < n) {
        dst[i] = src[i];
        i++;
    }
}

int main() {
    const size_t size = 1024 * 1024;
    char *src = malloc(size);
    char *dst1 = malloc(size);
    char *dst2 = malloc(size);

    // 初始化源数据
    memset(src, 'A', size);

    // 测试未优化的版本
    unoptimized_copy(dst1, src, size);

    // 测试优化的版本
    optimized_copy(dst2, src, size);

    free(src);
    free(dst1);
    free(dst2);

    return 0;
}
```

## 实践练习

1. 基本调试实验
```bash
# 创建测试程序
cat > debug_test.c << EOL
#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = NULL;
    *ptr = 42;  // 段错误
    return 0;
}
EOL

# 编译和调试
gcc -g debug_test.c -o debug_test
gdb ./debug_test
```

2. 内存调试实验
```bash
# 创建内存测试程序
cat > memory_test.c << EOL
#include <stdio.h>
#include <stdlib.h>

int main() {
    char *ptr = malloc(10);
    ptr[10] = 'A';  // 越界访问
    free(ptr);
    return 0;
}
EOL

# 编译和检查
gcc memory_test.c -o memory_test
valgrind ./memory_test
```

3. 性能调试实验
```bash
# 创建性能测试程序
cat > perf_test.c << EOL
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main() {
    clock_t start = clock();

    // 执行一些操作
    int *arr = malloc(1000000 * sizeof(int));
    for (int i = 0; i < 1000000; i++) {
        arr[i] = i;
    }
    free(arr);

    clock_t end = clock();
    printf("Time: %f seconds\n", 
           (double)(end - start) / CLOCKS_PER_SEC);
    return 0;
}
EOL

# 编译和分析
gcc -pg perf_test.c -o perf_test
./perf_test
gprof perf_test gmon.out
```

